// Catalogue of the Blender-built street buildings (public/models/buildings/*.glb, generated by
// tools/blender/build_*.py). Footprints and heights mirror the VARIANTS lists in those scripts:
// the street builder needs them for lots and collision before any model has loaded.
//
// A model's front faces local -z with its origin at the middle of the frontage on the pavement.
// `corner` models have a second street face on their local -x side.

export type BuildingKind = 'zakkyo' | 'office' | 'tower' | 'shophouse' | 'manshon' | 'canalfront' | 'yokocho' | 'boutique' | 'machi';

export interface BuildingModel {
  kind: BuildingKind;
  id: string;
  /** Frontage, depth and height in metres. */
  w: number;
  d: number;
  h: number;
  corner?: boolean;
}

